import sys,os;sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from common8 import *
SN=E('English','እንግሊዝኛ')
GB='en-GB'
def eq(en,am,opts,a=0,say=None):
    d={'q':E(en,am) if am else en,'o':[o if isinstance(o,str) else E(*o) for o in opts],'a':a}
    if say: d['say']=say;d['sayLang']=GB
    return d
def sq(sent,opts,a=0): return {'say':sent.replace('___',opts[a]),'sayLang':GB,'q':sent,'o':opts,'a':a}
def read(ptitle,paras,items): return {'title':E('Read and answer','አንብቡና መልሱ'),'type':'quiz','tip':E('Listen to the passage, read it yourself, then answer.','ጽሑፉን አዳምጡ፣ ራሳችሁ አንብቡ፣ ከዚያ መልሱ።'),'passage':{'title':ptitle,'paras':paras,'say':' '.join(paras),'sayLang':GB},'items':items}
def wm(pairs): return match(('Word meanings','የቃላት ፍቺ'),('Match each word from the unit with its meaning.','ከክፍሉ የተወሰዱ ቃላትን ከፍቺያቸው ጋር አዛምዱ።'),[[(a,b) for a,b in pairs]])
def sp(w,b,e,am): return {'w':w,'blanks':b,'e':e,'am':am}
def U(n,title,data,extra,exam,nt,summ):
    data=dict(data);data['lang']=GB
    unit(f'g8-english-{n}','english',SN,E(f'Unit {n}',f'ክፍል {n}'),E(*title),E(f'Built on the Grade 8 English student textbook (FDRE Ministry of Education), Unit {n}: {title[0]}.',f'በ8ኛ ክፍል የእንግሊዝኛ መጽሐፍ (የኢፌዴሪ ትምህርት ሚኒስቴር) ክፍል {n} ({title[1]}) ላይ የተመሰረተ።'),'K1.engMissions',data,extra,exam,nt,summ)

