U(6,('Afforestation','ደን ማልማት'),
 {'listen':[['tree','🌳','ዛፍ'],['seedling','🌱','ችግኝ'],['forest','🌲','ደን'],['leaf','🍃','ቅጠል'],['soil','🟫','አፈር'],['rain','🌧️','ዝናብ']],
  'spell':[sp('nursery',[1,5],'🪴','የችግኝ ጣቢያ'),sp('erosion',[1,4],'🏞️','መሸርሸር'),sp('shade',[2],'⛱️','ጥላ')],
  'sentences':[['Trees','which','grow','near','rivers','protect','the','soil.'],['Green','Legacy,','which','began','in','2019,','has','planted','billions','of','seedlings.']]},
 [read('Green Legacy',['Ethiopia lost much of its forest during the last century. Forests are important because they give shade, protect the soil and help bring rain.','The Green Legacy campaign, which began in 2019, has planted billions of seedlings. Students who join the campaign plant trees in school compounds. Trees that are cared for after planting have the best chance of surviving.'],
  [eq('Why are forests important?','ደኖች ለምን ይጠቅማሉ?',['they protect soil and help bring rain','they cause floods','they stop farming']),eq('When did Green Legacy begin?','አረንጓዴ አሻራ የጀመረው መቼ ነው?',['2019','1999','2025']),eq('Which trees survive best?','የተሻለ የሚጸድቁት ዛፎች?',['trees that are cared for','trees planted in sand','trees with no water'])]),
  quiz(('Adjective suffixes and relative clauses','የቅጽል ቅጥያዎችና relative clauses'),('Suffixes make adjectives: use → useful, care → careless, beauty → beautiful, wood → wooden, danger → dangerous. Defining relative clauses identify (Trees that are cared for survive). Non-defining clauses add extra information between commas (Green Legacy, which began in 2019, …).','ቅጥያዎች ቅጽል ይሠራሉ፦ use → useful፣ care → careless፣ beauty → beautiful፣ danger → dangerous። Defining relative clause ይለያል (Trees that are cared for survive)። Non-defining ተጨማሪ መረጃ በኮማ መካከል ይሰጣል (Green Legacy, which began in 2019, …)።'),[
   sq('Trees are very ___ to people.',['useful','useless','usefully']),sq('Cutting forests is ___ for the soil.',['dangerous','dangerful','danger']),sq('The students ___ planted trees got prizes.',['who','which','where']),sq('Wanza, ___ grows fast, gives good shade.',['which','who','that'])]),
  wm([('afforestation','planting new forests'),('seedling','a very young plant'),('erosion','soil being washed or blown away'),('survive','to stay alive')])],
 [sq('A forest ___ has many birds is healthy.',['that','who','where']),eq('Adjective from "beauty"','ከ"beauty" የሚወጣ ቅጽል',['beautiful','beautyful','beautious']),eq('Which is non-defining?','non-defining የሆነው?',['Lake Tana, which is the largest lake in Ethiopia, has islands.','The lake that is near my village is small.'],say='Lake Tana, which is the largest lake in Ethiopia, has islands.'),eq('Trees reduce…','ዛፎች የሚቀንሱት…',['soil erosion','rain','oxygen'])],
 notes(('Planting and caring for trees protects soil and water; we describe them with adjective suffixes and relative clauses.','ዛፍ መትከልና መንከባከብ አፈርንና ውኃን ይጠብቃል፤ በቅጽል ቅጥያዎችና በrelative clauses እንገልጻቸዋለን።'),
  [('Benefits of forests; Green Legacy.','የደን ጥቅሞች፤ አረንጓዴ አሻራ።'),('Suffixes: -ful, -less, -ous, -en, -al.','ቅጥያዎች፦ -ful, -less, -ous, -en, -al።'),('Defining: who/which/that, no commas.','Defining፦ who/which/that፣ ኮማ የለም።'),('Non-defining: who/which, with commas.','Non-defining፦ who/which፣ ከኮማ ጋር።')],
  [('afforestation','planting forests','ደን ማልማት'),('suffix','an ending added to a word','ቅጥያ'),('relative clause','a clause that describes a noun','ገላጭ ሐረግ')],('Who for people, which for things, commas for extras.','who ለሰው፣ which ለነገር፣ ኮማ ለተጨማሪ።'),
  [(('Join with who: "The girl planted 20 trees. She won a prize."','በwho አጣምሩ'),'The girl who planted 20 trees won a prize.'),(('Make adjectives: care, danger','ቅጽል አድርጉ፦ care, danger'),'careful/careless, dangerous')],
  (('School tree adoption','የትምህርት ቤት ዛፍ ጉዲፈቻ'),('Trees die when no one cares for them. Let each student adopt and track a tree.','ማንም ካልተንከባከባቸው ዛፎች ይሞታሉ። እያንዳንዱ ተማሪ ዛፍ ወስዶ ይከታተል።'),[('Number every school tree.','እያንዳንዱን የትምህርት ቤት ዛፍ ቁጥር ስጡ።'),('Assign each to a student with a name tag.','ለእያንዳንዱ ተማሪ በስም መለያ ስጡ።'),('Record height monthly.','በየወሩ ቁመቱን መዝግቡ።'),('Report survival rates at the end of the year.','በዓመቱ መጨረሻ የመጽደቅ መጠንን ሪፖርት አድርጉ።')])),
 sm(('Trees and describing words','ዛፎችና ገላጭ ቃላት'),[('Forests','ደኖች'),('Adjective suffixes','የቅጽል ቅጥያዎች'),('Defining clauses','Defining'),('Non-defining clauses','Non-defining')]))

