U(7,('Charity','በጎ አድራጎት'),
 {'listen':[['donate','🎁','መለገስ'],['volunteer','🙋','በጎ ፈቃደኛ'],['orphan','🧒','ወላጅ አልባ'],['elderly','👵','አረጋዊ'],['food','🍲','ምግብ'],['help','🤝','እርዳታ']],
  'spell':[sp('charity',[2,5],'💝','በጎ አድራጎት'),sp('kind',[1],'😊','ደግ'),sp('share',[2],'🤲','ማካፈል')],
  'sentences':[['We','were','collecting','clothes','when','the','bus','arrived.'],['Mekedonia','helps','elderly','and','mentally','ill','people.']]},
 [read('A Saturday at the shelter',['Last Saturday our school club visited a shelter for elderly people. While some students were cleaning the rooms, others were cooking lunch.','At noon an old man told us a story about his childhood. We listened quietly. Before we left, we gave the residents soap and blankets that we had collected. Charity is not only about money; time and kindness are gifts too.'],
  [eq('Where did the club go?','ክበቡ የት ሄደ?',['to a shelter for elderly people','to a market','to a stadium']),eq('What were some students doing while others cooked?','ሌሎች ሲያበስሉ አንዳንዶቹ ምን እያደረጉ ነበር?',['cleaning the rooms','sleeping','playing football']),eq('Main message','ዋናው መልእክት',['time and kindness are gifts too','charity is only money','old people need nothing'])]),
  quiz(('Past simple and past continuous (while/when)','Past simple እና past continuous (while/when)'),('Use while + past continuous for two long actions at the same time (While some were cleaning, others were cooking). Use when + past simple for a short action that interrupts (We were eating when he arrived).','ሁለት ረጅም ድርጊቶች በአንድ ጊዜ ሲሆኑ while + past continuous (While some were cleaning, others were cooking)። አጭር ድርጊት ሲያቋርጥ when + past simple (We were eating when he arrived)።'),[
   sq('While we ___ , it started to rain.',['were walking','walked','walk']),sq('She was cooking when the guests ___.',['arrived','were arrive','arrive']),sq('They ___ blankets last week.',['donated','were donate','donating']),sq('What ___ you doing at 10 a.m.?',['were','was','did'])]),
  wm([('donate','to give for free'),('volunteer','a person who works without pay'),('shelter','a place that gives protection'),('resident','a person who lives in a place')])],
 [sq('I ___ my homework when the lights went out.',['was doing','did','do']),sq('We ___ the shelter last Saturday.',['visited','were visit','visit']),eq('Use while with…','while የምንጠቀመው ከ… ጋር',['two long actions at the same time','one short action','future plans']),eq('A volunteer…','በጎ ፈቃደኛ…',['works without pay','is always paid','never helps'])],
 notes(('Charity means giving money, time or kindness; we narrate past events with the past simple and past continuous using when and while.','በጎ አድራጎት ገንዘብን፣ ጊዜንና ደግነትን መስጠት ነው፤ ያለፉ ሁነቶችን በpast simple እና past continuous ከwhen እና while ጋር እንተርካለን።'),
  [('Reading about volunteering.','ስለ በጎ ፈቃደኝነት ማንበብ።'),('Vocabulary: donate, volunteer, shelter.','ቃላት፦ donate, volunteer, shelter።'),('while + past continuous.','while + past continuous።'),('when + past simple interrupts.','when + past simple ያቋርጣል።')],
  [('charity','helping people in need','በጎ አድራጎት'),('donate','to give freely','መለገስ'),('volunteer','unpaid helper','በጎ ፈቃደኛ')],('While = both long; when = short interrupts.','While = ሁለቱም ረጅም፤ when = አጭር ያቋርጣል።'),
  [(('Join with while: "I was reading. My sister was cooking."','በwhile አጣምሩ'),'While I was reading, my sister was cooking.'),(('Give two ways to help without money','ያለ ገንዘብ መርዳት የሚቻልባቸው ሁለት መንገዶች'),'volunteering time, teaching younger children')],
  (('Book-share library','የመጻሕፍት መጋሪያ ቤተ መጻሕፍት'),('Old textbooks can help younger students. Start a book-share corner.','አሮጌ መጻሕፍት ታናናሽ ተማሪዎችን ሊረዱ ይችላሉ። የመጻሕፍት መጋሪያ ጥግ ጀምሩ።'),[('Collect used books at the end of the year.','በዓመቱ መጨረሻ ያገለገሉ መጻሕፍትን ሰብስቡ።'),('Sort them by grade and subject.','በክፍልና በትምህርት ዓይነት ለዩ።'),('Lend them with a simple card system.','በቀላል የካርድ ሥርዓት አውሱ።'),('Write a short English story about the project.','ስለ ፕሮጀክቱ አጭር የእንግሊዝኛ ታሪክ ጻፉ።')])),
 sm(('Giving and telling stories','መስጠትና መተረክ'),[('Reading','ንባብ'),('Vocabulary','ቃላት'),('while + continuous','while + continuous'),('when + simple','when + simple')]))

