U(8,('Personal Hygiene','የግል ንጽሕና'),
 {'listen':[['soap','🧼','ሳሙና'],['toothbrush','🪥','የጥርስ ብሩሽ'],['towel','🧺','ፎጣ'],['shower','🚿','ሻወር'],['nails','💅','ጥፍሮች'],['water','💧','ውኃ']],
  'spell':[sp('clean',[2],'✨','ንጹሕ'),sp('germs',[1,3],'🦠','ጀርሞች'),sp('teeth',[2],'🦷','ጥርሶች')],
  'sentences':[['I','always','wash','my','hands','before','meals.'],['She','brushes','her','teeth','twice','a','day.']]},
 [read('Small habits, big health',['Germs are tiny living things that can make us ill. Most of them spread through dirty hands. That is why we should always wash our hands with soap after using the toilet and before eating.','Health workers say we should brush our teeth twice a day, wash our bodies every day and cut our nails once a week. We should never share toothbrushes. Clean habits protect us and the people around us.'],
  [eq('How do most germs spread?','አብዛኞቹ ጀርሞች እንዴት ይተላለፋሉ?',['through dirty hands','through books','through sunlight']),eq('How often should we brush our teeth?','ጥርሳችንን ስንት ጊዜ መቦረሽ አለብን?',['twice a day','once a month','never']),eq('What should we never share?','ፈጽሞ መጋራት የሌለብን?',['toothbrushes','ideas','smiles'])]),
  quiz(('Adverbs of frequency','የድግግሞሽ ተውሳከ ግሦች'),('always (100%), usually, often, sometimes, rarely, never (0%). They go before the main verb (I always wash) but after be (He is never late). Expressions like twice a day go at the end.','always (100%)፣ usually፣ often፣ sometimes፣ rarely፣ never (0%)። ከዋናው ግሥ በፊት ይገባሉ (I always wash)፤ ከbe በኋላ ግን (He is never late)። እንደ twice a day ያሉት በመጨረሻ ይገባሉ።'),[
   sq('I ___ wash my hands before meals.',['always','ever','yet']),eq('Correct word order','ትክክለኛው ቅደም ተከተል',['She is never late.','She never is late.','Never she is late.'],say='She is never late.'),sq('We cut our nails once ___ week.',['a','the','in']),sq('You should ___ share a towel with a sick person.',['never','always','usually'])]),
  sortm(('Healthy or unhealthy habit?','ጤናማ ወይስ ጤናማ ያልሆነ ልማድ?'),('Sort each habit.','እያንዳንዱን ልማድ ለዩ።'),[('Healthy','ጤናማ'),('Unhealthy','ጤናማ ያልሆነ')],[('washing hands with soap',0),('brushing teeth twice a day',0),('changing socks daily',0),('sharing a toothbrush',1),('biting your nails',1),('eating with dirty hands',1)],say=True)],
 [sq('He ___ forgets to brush his teeth. (0%)',['never','always','often']),eq('Adverbs of frequency go…','የድግግሞሽ ተውሳከ ግሦች የሚገቡት…',['before the main verb, after be','always at the start','after the object']),sq('I take a shower ___ day.',['every','all','each of']),eq('Germs are…','ጀርሞች…',['tiny living things that cause illness','vitamins','vegetables'])],
 notes(('Simple daily habits stop germs; we describe how often we do them with adverbs of frequency.','ቀላል ዕለታዊ ልማዶች ጀርሞችን ያስቆማሉ፤ ምን ያህል ጊዜ እንደምናደርጋቸው በድግግሞሽ ተውሳከ ግሦች እንገልጻለን።'),
  [('Hygiene: hands, teeth, body, nails.','ንጽሕና፦ እጅ፣ ጥርስ፣ ሰውነት፣ ጥፍር።'),('How germs spread.','ጀርሞች እንዴት እንደሚተላለፉ።'),('always, usually, often, sometimes, rarely, never.','always, usually, often, sometimes, rarely, never።'),('Position: before main verb, after be.','ቦታ፦ ከዋና ግሥ በፊት፣ ከbe በኋላ።')],
  [('hygiene','keeping clean to stay healthy','ንጽሕና'),('germ','a tiny thing that causes illness','ጀርም'),('frequency','how often','ድግግሞሽ')],('Always … never: before the verb, after be.','Always … never፦ ከግሥ በፊት፣ ከbe በኋላ።'),
  [(('Put "usually" in: "I wash my face in the morning."','"usually" አስገቡ'),'I usually wash my face in the morning.'),(('Two times we must wash our hands','እጃችንን መታጠብ ያለብን ሁለት ጊዜያት'),'after the toilet, before eating')],
  (('Tippy-tap hand-washing station','የቲፒ-ታፕ የእጅ መታጠቢያ'),('Many schools lack taps. Build a foot-operated hand-washing station from a jerrycan.','ብዙ ትምህርት ቤቶች ቧንቧ የላቸውም። ከጀሪካን በእግር የሚሠራ የእጅ መታጠቢያ ሥሩ።'),[('Collect a jerrycan, sticks and string.','ጀሪካን፣ እንጨትና ገመድ ሰብስቡ።'),('Build the frame and foot pedal.','ፍሬሙንና የእግር መርገጫውን ሥሩ።'),('Hang soap on a string.','ሳሙናን በገመድ አንጠልጥሉ።'),('Write an English sign with adverbs of frequency.','በድግግሞሽ ተውሳከ ግሦች የእንግሊዝኛ ምልክት ጻፉ።')])),
 sm(('Clean habits, how often','ንጹሕ ልማዶች፣ ስንት ጊዜ'),[('Hygiene','ንጽሕና'),('Germs','ጀርሞች'),('Frequency adverbs','የድግግሞሽ ተውሳኮች'),('Word position','የቃል ቦታ')]))

